#!/bin/bash
set -e

# Session security + visibility:
# - Auto-logout after 30 minutes of no mouse/keyboard/touch activity
#   (AppShell.js). Login page shows a friendly notice when redirected
#   this way.
# - Heartbeat updates profiles.last_active_at every ~60s while the app
#   is open (database column already added live).
# - User Management now shows a live Online / Away / Last seen status
#   per staff member.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/(main)/users"
echo "" | base64 -d > "app/(main)/users/actions.js"
echo "Wrote app/(main)/users/actions.js"

mkdir -p "app/components"
echo "" | base64 -d > "app/components/AppShell.js"
echo "Wrote app/components/AppShell.js"

mkdir -p "app/login"
echo "" | base64 -d > "app/login/page.js"
echo "Wrote app/login/page.js"

mkdir -p "app/(main)/users"
echo "" | base64 -d > "app/(main)/users/page.js"
echo "Wrote app/(main)/users/page.js"

git add "app/(main)/users/actions.js" "app/components/AppShell.js" "app/login/page.js" "app/(main)/users/page.js"
git commit -m "Add 30-min idle auto-logout and live Online/Away status in User Management"
git push

echo "Done."
